    if (filled && basePath.contains('ic_')) {
      return basePath.replaceFirst('.png', '_filled.png');
    }
    return basePath;
  }

  // Get placeholder based on type
  static String getPlaceholder(String type) {
    switch (type) {
      case 'user':
        return Assets.userPlaceholder;
      case 'driver':
        return Assets.driverPlaceholder;
      case 'bus':
        return Assets.busPlaceholder;
      case 'cargo':
        return Assets.cargoPlaceholder;
      case 'ticket':
        return Assets.ticketPlaceholder;
      default:
        return Assets.userPlaceholder;
    }
  }

  // Get flag based on language code
  static String getFlag(String languageCode) {
    switch (languageCode) {
      case 'en':
        return Assets.flagEn;
      case 'am':
        return Assets.flagAm;
      default:
        return Assets.flagEn;
    }
  }
}

